mapper.select:
WITH tb_plan_temp AS (SELECT em.employee_number ,em.full_name_local ,em.grade_title ,ap.time_and_attendance_date ,ap.a_day_of_the_week_code ,ac.time_and_attendance_type_code ,ap.time_and_attendance_code ,ap.time_attend_detail_code ,ap.shift_type_code ,ap.night_shift_flag ,ap.overtime_sum_hours ,ac.update_enable_flag ,lgvatt_common_pkg.get_holiday_flag(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,ap.shift_type_code ,trunc(to_date(#{attDate}, 'dd/mm/yyyy')) + 1) AS holiday_flag ,em.organization_id FROM tb_att_plan_n ap ,emp_master em ,tb_att_code_c ac WHERE 1 = 1 AND ap.time_and_attendance_date = trunc(to_date(#{attDate}, 'dd/mm/yyyy') + 1) AND ap.employee_no = em.employee_number AND ap.time_and_attendance_code = ac.time_and_attendance_code AND ap.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} -- AND em.status = 'Active Assignment' AND em.flsa_yn = 'N' AND em.fse_yn = 'N') ,tb_actual_temp AS (SELECT em.employee_number ,em.full_name_local ,em.grade_title ,ar.time_and_attendance_date ,ar.a_day_of_the_week_code ,ac.time_and_attendance_type_code ,ar.time_and_attendance_code ,ar.time_attend_detail_code ,ar.shift_type_code ,ar.night_shift_flag ,ar.evening_meal_flag ,ar.work_start_time ,ar.time_attend_input_reason_desc ,ar.overtime_sum_hours ,ar.weekday_overtime_hours ,ar.holiday_overtime_hours ,ar.public_holiday_overtime_hours ,ar.weekday_night_overtime_hours ,ar.weekday_ot_af_night_work_hours ,ar.holiday_night_overtime_hours ,ar.public_holiday_night_ot_hours ,ar.normal_night_overtime_hours ,ar.tardy_hours ,ar.early_leave_hours ,ar.going_out_hours ,ar.special_bonus_hours ,ar.helpcall_support_hours ,ac.update_enable_flag ,lgvatt_common_pkg.get_holiday_flag(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,ar.shift_type_code ,trunc(to_date(#{attDate}, 'dd/mm/yyyy'))) AS holiday_flag ,to_char(lgvatt_common_pkg.get_idcard_inout_time(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,em.employee_number ,trunc(to_date(#{attDate}, 'dd/mm/yyyy')) ,'IN'), 'HH24:MI') AS check_in ,to_char(lgvatt_common_pkg.get_idcard_inout_time(#{LGVHR_PROJECT_SESSION.subsidiaryCode} ,em.employee_number ,trunc(to_date(#{attDate}, 'dd/mm/yyyy')) ,'OUT'), 'HH24:MI') AS check_out ,em.organization_id FROM tb_att_result_n ar ,emp_master em ,tb_att_code_c ac WHERE 1 = 1 AND ar.time_and_attendance_date = trunc(to_date(#{attDate}, 'dd/mm/yyyy')) AND ar.employee_no = em.employee_number AND ar.time_and_attendance_code = ac.time_and_attendance_code AND ar.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} -- AND em.status = 'Active Assignment' AND em.flsa_yn = 'N' AND em.fse_yn = 'N') SELECT tat.employee_number AS employee_no ,tat.full_name_local AS employee_name ,tat.grade_title AS employee_grade ,to_char(tpt.time_and_attendance_date, 'dd/mm/yyyy') AS plan_date ,tpt.time_and_attendance_type_code AS plan_attendance_type ,tpt.time_and_attendance_code AS plan_attendance_detail ,tpt.time_attend_detail_code AS plan_attend_detail_reason ,tpt.shift_type_code AS plan_shift_code ,tpt.night_shift_flag AS plan_day_night ,nvl(tpt.overtime_sum_hours, 0) AS plan_o_t ,to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') AS actual_date ,tat.time_and_attendance_type_code AS actual_attendance_type ,tat.time_and_attendance_code AS actual_attendance_detail ,tat.time_attend_detail_code AS actual_attend_detail_reason ,tat.shift_type_code AS actual_shift_code ,tat.night_shift_flag AS actual_day_night ,nvl(tat.evening_meal_flag, 'N') AS actual_dinner_chk ,COALESCE((select distinct fl.work_start_time from tb_att_flexible_result_n fl where fl.PROGRESS_STATUS_CODE = '40' AND fl.employee_no = tat.employee_number and fl.time_and_attendance_date = tat.time_and_attendance_date), tat.work_start_time ) AS actual_start_tm ,nvl(tat.overtime_sum_hours, 0) AS actual_o_t ,tat.time_attend_input_reason_desc AS time_attend_input_reason_desc ,lgvatt_ot_calculation_pkg.get_ot_total(#{LGVHR_PROJECT_SESSION.subsidiaryCode}, tat.employee_number, tat.time_and_attendance_date,tat.time_and_attendance_date, 'month_total_ot_yyyymm') AS month_total_overtime ,(CASE WHEN tat.shift_type_code IN ('2A','2B') THEN '0' ELSE lgvatt_ot_level_pkg.get_ot_level(#{LGVHR_PROJECT_SESSION.subsidiaryCode}, tat.employee_number, TO_CHAR(tat.time_and_attendance_date,'YYYYMM'), 'request_lower_limit') END ) as overtime_limit ,nvl(tat.weekday_overtime_hours, 0) AS weekday ,nvl(tat.holiday_overtime_hours, 0) AS weekday_holiday ,nvl(tat.public_holiday_overtime_hours, 0) AS public_holiday ,nvl(tat.weekday_night_overtime_hours, 0) AS at_night_weekday ,nvl(tat.weekday_ot_af_night_work_hours, 0) AS at_night_weekday_after_o_t ,nvl(tat.holiday_night_overtime_hours, 0) AS at_night_weekday_holiday ,nvl(tat.public_holiday_night_ot_hours, 0) AS at_night_public_holiday ,nvl(tat.normal_night_overtime_hours, 0) AS night_normal ,nvl(tat.tardy_hours, 0) AS deduction_lateness ,nvl(tat.early_leave_hours, 0) AS deduction_leaving_early ,nvl(tat.going_out_hours, 0) AS deduction_going_out ,nvl(tat.special_bonus_hours, 0) AS special_bonus ,nvl(tat.helpcall_support_hours, 0) AS help_call ,tpt.update_enable_flag AS plan_update_enable ,tat.update_enable_flag AS actual_update_enable ,tpt.holiday_flag AS plan_holiday_flag ,(CASE WHEN EXISTS (select 1 from tb_att_flexible_result_n fl where fl.PROGRESS_STATUS_CODE = '40' AND fl.employee_no = tat.employee_number and fl.time_and_attendance_date = tat.time_and_attendance_date) then 'X' WHEN tat.shift_type_code IN ('2A','2B') THEN 'T' -- HMS_20260601 Add 2A,2B Shift ELSE tat.holiday_flag END) AS actual_holiday_flag ,tat.check_in AS actual_in_time ,tat.check_out AS actual_out_time ,tat.time_and_attendance_code AS original_att_code ,CASE WHEN to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.check_in, 'DD/MM/YYYY HH24:MI') >= to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') + INTERVAL '-5' MINUTE THEN 'Y' ELSE 'N' END AS illegal_in_time_flag ,CASE WHEN tat.shift_type_code LIKE '1%' THEN ( CASE WHEN to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') < to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' 17:00', 'DD/MM/YYYY HH24:MI') AND to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') >= to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' 08:00', 'DD/MM/YYYY HH24:MI') THEN ( CASE WHEN to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.check_out, 'DD/MM/YYYY HH24:MI') <= to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') + INTERVAL '9' HOUR THEN 'Y' ELSE 'N' END ) -- 1부제 Day ELSE ( CASE WHEN to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.check_out, 'DD/MM/YYYY HH24:MI') + INTERVAL '24' HOUR <= to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') + INTERVAL '9' HOUR THEN 'Y' ELSE 'N' END ) -- 1부제 Night END ) ELSE ( CASE WHEN to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') < to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' 20:00', 'DD/MM/YYYY HH24:MI') AND to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') >= to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' 08:00', 'DD/MM/YYYY HH24:MI') THEN ( CASE WHEN to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.check_out, 'DD/MM/YYYY HH24:MI') <= to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') + INTERVAL '12' HOUR THEN 'Y' ELSE 'N' END ) -- 2부제 Day ELSE ( CASE WHEN to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.check_out, 'DD/MM/YYYY HH24:MI') + INTERVAL '24' HOUR <= to_date(to_char(tat.time_and_attendance_date, 'dd/mm/yyyy') || ' ' || tat.work_start_time, 'DD/MM/YYYY HH24:MI') + INTERVAL '12' HOUR THEN 'Y' ELSE 'N' END ) -- 2부제 Night END ) END AS illegal_out_time_flag ,'N' AS is_edit_ot FROM tb_plan_temp tpt ,tb_actual_temp tat WHERE 1 = 1 AND tpt.employee_number = tat.employee_number
AND tat.organization_id = #{orgId}
AND tat.shift_type_code = #{shiftCode}
AND tpt.employee_number like '%' || UPPER(#{employeeNo}) || '%'
AND UPPER(tpt.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
ORDER BY tpt.grade_title, tpt.employee_number
